                serialNum: 10,
                listenerCount: 69265,
                name: "Vol.010 昌叔：大家坐稳扶好，我要开始搞笑了",
                id: 2492840384,
                createTime: 1632293624723,
                description:
                  "大家好，新一期的「笑果小酒馆」来了。\n\n本期请到的嘉宾是脱口秀和漫才演员：昌叔。\n\n如果大家感兴趣的话，也可以做一做这个问卷。如果你也很喜欢自己的答案，可以在微博上@笑果工厂，我们每周会从里面选一位观众送出点粗糙小礼物。\n\n问卷如下：\n\n1、最近你有什么新发现吗\n2、与人交往中你希望呈现什么样的形象\n3、你有没有想成为的人，是否有类似形象供你参考\n4、目前为止发生在你身上最好的一件事是什么\n5、目前为止发生在你身上最坏的一件事是什么\n6、你是什么时候意识到自己是个普通人的，或者你什么时候意识到自己是个天才\n7、你觉得自己最珍贵的品质是什么\n8、你觉得自己最恶劣的品质是什么\n9、有被闪电击中或起鸡皮疙瘩这样的体验吗\n10、你有喜欢的电影吗，喜欢哪个电影导演\n11、你喜欢阅读吗，喜欢哪位作家\n12、如果要学一门艺术你会选择学什么\n13、你对自己最满意的一次选择是什么\n14、你有没有很想说但似乎没有语境说的东西\n15、你的终极目标是什么\n16、你觉得自己是个好人吗\n17、世界上有让你深恶痛绝的人吗\n18、世界上有让你五体投地的人吗\n19、你最喜欢哪个城市\n20、你最喜欢什么气味",
